record.field:
ledger = model._revoke_orphan_credentials(apply=False)
lines = ['%(domain)s %(username)s %(sid)s %(action)s' % row for row in ledger]
log('Orphaned SIP credentials (dry run): %s rows\n%s' % (len(ledger), '\n'.join(lines)))
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Orphaned SIP credentials (dry run)',
        'message': '%s orphaned credentials found. Ledger is in the server log.' % len(ledger),
        'type': 'info',
        'sticky': True,
    },
}
